import java.io.*;
import java.util.*;

public class E {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            all.append(line).append(' ');
        }

        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        long[] a = new long[3];
        long[] b = new long[3];

        for (int i = 0; i < 3; i++) a[i] = Long.parseLong(st.nextToken());
        for (int i = 0; i < 3; i++) b[i] = Long.parseLong(st.nextToken());

        long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        long min = Math.max(0, a[0] + b[1] - n)
                 + Math.max(0, a[1] + b[2] - n)
                 + Math.max(0, a[2] + b[0] - n);

        System.out.println(min + " " + max);
    }
}
